{
  "model": "openai/gpt-4o-mini",
  "input": "Respond with a single text part whose content is \"hello world\". Do not emit any citation parts.",
  "max_output_tokens": 512,
  "text": {
    "format": {
      "type": "json_schema",
      "name": "reply",
      "strict": true,
      "schema": {
        "$defs": {
          "TextPart": {
            "additionalProperties": false,
            "properties": {
              "type": {
                "const": "text",
                "title": "Type",
                "type": "string"
              },
              "text": {
                "title": "Text",
                "type": "string"
              }
            },
            "required": [
              "type",
              "text"
            ],
            "title": "TextPart",
            "type": "object"
          },
          "WebCitation": {
            "additionalProperties": false,
            "properties": {
              "type": {
                "const": "cite:web",
                "title": "Type",
                "type": "string"
              },
              "url": {
                "title": "Url",
                "type": "string"
              }
            },
            "required": [
              "type",
              "url"
            ],
            "title": "WebCitation",
            "type": "object"
          }
        },
        "additionalProperties": false,
        "properties": {
          "parts": {
            "items": {
              "anyOf": [
                {
                  "$ref": "#/$defs/TextPart"
                },
                {
                  "$ref": "#/$defs/WebCitation"
                }
              ]
            },
            "title": "Parts",
            "type": "array"
          }
        },
        "required": [
          "parts"
        ],
        "title": "Reply",
        "type": "object"
      }
    }
  }
}

